SELECT COUNT(*) FROM users as u, comments as c, posts as p, badges as b WHERE u.Id = c.UserId AND u.Id = p.OwnerUserId AND u.Id = b.UserId AND u.Views=0 AND u.DownVotes>=0 AND u.DownVotes<=60 AND c.Score=0 AND p.Score>=-2 AND p.CommentCount>=0 AND p.CommentCount<=12 AND p.FavoriteCount>=0 AND p.FavoriteCount<=6
